package com.example.yiyan;
import android.app.*;import android.os.*;import android.view.*;import android.widget.*;import android.content.*;import java.util.*;
public class ManageQuotesActivity extends Activity{
 LinearLayout flow;Spinner categoryFilter;final ArrayList<Quote> items=new ArrayList<>();final ArrayList<String> categories=new ArrayList<>();
 public void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_manage_quotes);flow=findViewById(R.id.quotes_flow);loadCategories();LinearLayout bar=new LinearLayout(this);bar.setOrientation(LinearLayout.HORIZONTAL);EditText input=new EditText(this);input.setHint("新分类");Button add=new Button(this);add.setText("添加");Button del=new Button(this);del.setText("删除当前分类");bar.addView(input,new LinearLayout.LayoutParams(0,-2,1));bar.addView(add);bar.addView(del);flow.addView(bar);categoryFilter=new Spinner(this);flow.addView(categoryFilter);refreshCategoryFilter();add.setOnClickListener(v->{String s=input.getText().toString().trim();if(!s.isEmpty()&&!categories.contains(s)){categories.add(s);saveCategories();input.setText("");refreshCategoryFilter();}});del.setOnClickListener(v->{Object s=categoryFilter.getSelectedItem();if(s!=null&&!s.toString().equals("全部")&&!s.toString().equals("哲学")){categories.remove(s.toString());saveCategories();refreshCategoryFilter();}});TextView title=new TextView(this);title.setText("一言管理 · 点击条目编辑");title.setTextSize(24);title.setTextColor(0xff24212a);title.setPadding(8,8,8,20);flow.addView(title);loadItems();EditText search=findViewById(R.id.search_quotes);search.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int a){}public void onTextChanged(CharSequence s,int st,int b,int c){render(s.toString());}public void afterTextChanged(android.text.Editable e){}});}
 void loadCategories(){categories.add("哲学");android.content.SharedPreferences p=getSharedPreferences("settings",0);for(String s:p.getStringSet("categories",new java.util.HashSet<String>()))if(!categories.contains(s))categories.add(s);}
 void saveCategories(){getSharedPreferences("settings",0).edit().putStringSet("categories",new java.util.HashSet<>(categories)).apply();}
 void refreshCategoryFilter(){ArrayList<String> values=new ArrayList<>();values.add("全部");values.addAll(categories);ArrayAdapter<String> a=new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,values);categoryFilter.setAdapter(a);categoryFilter.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onItemSelected(android.widget.AdapterView<?> p,View v,int pos,long id){render("");}public void onNothingSelected(android.widget.AdapterView<?> p){}});}
 void loadItems(){android.content.SharedPreferences p=getSharedPreferences("settings",0);String saved=p.getString("editable_library","");if(saved.isEmpty())for(Quote q:QuoteLibrary.ALL)if(q.kind.equals("译写 / 意译"))items.add(q);else for(String line:saved.split("\\n")){String[] x=line.split("\\|",-1);if(x.length>=3&&!x[0].trim().isEmpty())items.add(new Quote(x[0].trim(),x[1].trim(),x[2].trim(),"用户编辑",x.length>=4?x[3].trim():"哲学"));}render("");}
 void render(String query){while(flow.getChildCount()>3)flow.removeViewAt(3);String q=query.trim().toLowerCase(Locale.ROOT),selected=categoryFilter==null?"全部":String.valueOf(categoryFilter.getSelectedItem());int n=1;for(Quote item:items){String hay=(item.text+" "+item.author+" "+item.work).toLowerCase(Locale.ROOT);if((!q.isEmpty()&&!hay.contains(q))||(!selected.equals("全部")&&!item.category.equals(selected)))continue;final int index=items.indexOf(item);TextView card=new TextView(this);card.setText("第 "+n++ +" 句 · "+item.category+"\n"+item.text+"\n— "+item.author+" · 《"+item.work+"》");card.setTextSize(16);card.setTextColor(0xff24212a);card.setPadding(20,18,20,18);card.setBackgroundColor(0xfffff9f0);card.setOnClickListener(v->edit(index));flow.addView(card,new LinearLayout.LayoutParams(-1,-2));Space gap=new Space(this);flow.addView(gap,new LinearLayout.LayoutParams(1,12));}}
 void edit(int index){Quote old=items.get(index);LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);EditText text=field(old.text,"句子"),author=field(old.author,"作者"),work=field(old.work,"出处 / 作品"),cat=field(old.category,"分类");box.addView(text);box.addView(author);box.addView(work);box.addView(cat);new AlertDialog.Builder(this).setTitle("编辑第 "+(index+1)+" 句").setView(box).setNegativeButton("取消",null).setPositiveButton("保存",(d,w)->{items.set(index,new Quote(text.getText().toString().trim(),author.getText().toString().trim(),work.getText().toString().trim(),"用户编辑",cat.getText().toString().trim().isEmpty()?"哲学":cat.getText().toString().trim()));persist();}).show();}
 EditText field(String value,String hint){EditText e=new EditText(this);e.setText(value);e.setHint(hint);e.setTextSize(16);return e;}
 void persist(){StringBuilder out=new StringBuilder();for(Quote q:items)if(!q.text.isEmpty()&&!q.author.isEmpty()&&!q.work.isEmpty())out.append(q.text).append("|").append(q.author).append("|").append(q.work).append("|").append(q.category).append("\n");getSharedPreferences("settings",0).edit().putString("editable_library",out.toString()).apply();android.util.Log.i("99YIYAN_LOG","保存分类一言库 "+items.size());sendBroadcast(new Intent(QuoteWidgetProvider.ACTION).setPackage(getPackageName()));render("");Toast.makeText(this,"已保存",Toast.LENGTH_SHORT).show();}
}
